<script lang="ts">
  import Badge from '../../components/ui/Badge.svelte';
  import Button from '../../components/ui/Button.svelte';
  import type { PreviewRunnerStore } from '../../lib/stores/preview-runner.svelte';
  let { model }: { model: PreviewRunnerStore } = $props();
  const locators = $derived(model.session?.events.filter((event) => event.locator) ?? []);
</script>

{#if model.session}
  <section class="mt-4 space-y-3 border-t border-border-subtle pt-4" aria-label="Preview session status">
    <div class="flex flex-wrap items-center gap-2"><h4 class="text-sm font-medium text-text-primary">{model.session.mode === 'record' ? 'Locator selection' : 'Preview checks'}</h4><Badge tone="neutral">{model.session.lifecycle.replaceAll('_', ' ')}</Badge></div>
    {#if model.session.can_continue}<p class="text-sm text-text-secondary" role="status">Use the separate test browser to sign in for each role: {model.session.roles.join(', ')}. Continue only when every test session is ready.</p><Button variant="primary" disabled={model.busy} onclick={() => void model.continueLogin()}>Test roles ready — continue</Button>{/if}
    <p class="text-xs text-text-muted">Leaving this workspace revokes its session. Cancellation does not undo changes already made to test data.</p>
