    {#if model.session.error}<p class="text-sm text-danger" role="alert">{model.session.error}</p>{/if}
    {#if model.session.capture_screenshots}<section class="space-y-3" aria-label="Screenshot review"><h4 class="text-sm font-medium text-text-primary">Optional screenshot evidence</h4><p class="text-xs text-warning">Images may contain sensitive information. Inspect each capture before keeping it for up to seven days. Images are excluded from portable memory and test exports.</p>{#if model.running}<div class="flex flex-wrap gap-2">{#each model.session.roles as role (role)}<Button size="sm" variant="secondary" disabled={model.busy} onclick={() => void model.capture(role)}>Request capture for {role}</Button>{/each}</div>{/if}{#each model.session.captures as capture (capture.id)}<article class="space-y-2 rounded-md border border-border-subtle p-3"><p class="text-sm text-text-primary">{capture.role} · {capture.retained ? 'Retained after review' : 'Pending your review'}</p><img src={capture.data_url} alt={`Test surface captured for ${capture.role}. Inspect for sensitive information before retaining.`} class="max-h-80 w-full object-contain" /><div class="flex flex-wrap gap-2">{#if !capture.retained}<Button size="sm" variant="secondary" disabled={model.busy} onclick={() => void model.reviewCapture(capture.id, true)}>I reviewed this image — retain</Button>{/if}<Button size="sm" variant="ghost" disabled={model.busy} onclick={() => void model.reviewCapture(capture.id, false)}>{capture.retained ? 'Delete retained image' : 'Discard image'}</Button></div></article>{/each}</section>{/if}
